/* Generated by scripts/build.cjs. */
const CONFIG=__CONFIG__;
const PREFIX='recetario-video-lab-', SHELL=PREFIX+'shell-'+CONFIG.build, MEDIA=PREFIX+'media-v4';
const base=new URL('./',self.location.href);
const allowedVideos=new Set(CONFIG.videos.map(p=>new URL(p,base).href));
self.addEventListener('install',event=>event.waitUntil((async()=>{
  const cache=await caches.open(SHELL);
  try{await cache.addAll(CONFIG.shell);}catch(error){await caches.delete(SHELL);throw error;}
})()));
self.addEventListener('message',event=>{
  if(event.data?.type==='ACTIVATE')self.skipWaiting();
  if(event.data?.type==='VERSION')event.ports[0]?.postMessage(CONFIG.build);
});
self.addEventListener('activate',event=>event.waitUntil((async()=>{
  const keys=await caches.keys();
  await Promise.all(keys.filter(k=>k.startsWith(PREFIX)&&k!==SHELL&&k!==MEDIA).map(k=>caches.delete(k)));
  await self.clients.claim();
})()));
function parseRange(header,size){
  const match=/^bytes=(\d*)-(\d*)$/.exec(header||'');if(!match||(!match[1]&&!match[2]))return null;
  let start=match[1]?Number(match[1]):Math.max(0,size-Number(match[2]));
  let end=match[1]?(match[2]?Math.min(Number(match[2]),size-1):size-1):size-1;
  return Number.isSafeInteger(start)&&Number.isSafeInteger(end)&&start<=end&&start<size?{start,end}:null;
}
async function mediaResponse(request){
  const cache=await caches.open(MEDIA),cached=await cache.match(request.url);
  if(!cached)return fetch(request);
  const range=request.headers.get('Range');if(!range)return cached;
  const blob=await cached.blob(),bounds=parseRange(range,blob.size);
  if(!bounds)return new Response(null,{status:416,headers:{'Content-Range':`bytes */${blob.size}`}});
  const {start,end}=bounds;
  return new Response(blob.slice(start,end+1),{status:206,headers:{'Content-Type':cached.headers.get('Content-Type')||'video/mp4','Content-Length':String(end-start+1),'Content-Range':`bytes ${start}-${end}/${blob.size}`,'Accept-Ranges':'bytes'}});
}
self.addEventListener('fetch',event=>{
  const request=event.request,url=new URL(request.url);
  if(request.method!=='GET'||url.origin!==base.origin||!url.pathname.startsWith(base.pathname))return;
  if(allowedVideos.has(url.href)){event.respondWith(mediaResponse(request));return;}
  event.respondWith((async()=>{
    const cache=await caches.open(SHELL);
    if(request.mode==='navigate')return (await cache.match(new URL('index.html',base).href))||fetch(request);
    return (await cache.match(request))||fetch(request);
  })());
});
